import{_ as e,o as r,c as h,a2 as t}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第三章 有限责任公司的设立和组织机构","description":"","frontmatter":{"title":"第三章 有限责任公司的设立和组织机构","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第三章：有限责任公司的设立和组织机构.md"},"headers":[],"relativePath":"blogs/CL/disanzhang：youxianzerengongsideshelihezuzhijigou.md","filePath":"blogs/CL/第三章：有限责任公司的设立和组织机构.md"}'),o={name:"blogs/CL/disanzhang：youxianzerengongsideshelihezuzhijigou.md"};function i(l,a,n,d,s,c){return r(),h("div",null,[...a[0]||(a[0]=[t('<h1 id="第三章-有限责任公司的设立和组织机构" tabindex="-1">第三章 有限责任公司的设立和组织机构 <a class="header-anchor" href="#第三章-有限责任公司的设立和组织机构" aria-label="Permalink to &quot;第三章 有限责任公司的设立和组织机构&quot;">​</a></h1><h3 id="第四十二条" tabindex="-1">第四十二条 <a class="header-anchor" href="#第四十二条" aria-label="Permalink to &quot;第四十二条&quot;">​</a></h3><p>二条有限责任公司由一个以上五十个以下股东出资设立。</p><h3 id="第四十三条" tabindex="-1">第四十三条 <a class="header-anchor" href="#第四十三条" aria-label="Permalink to &quot;第四十三条&quot;">​</a></h3><p>三条有限责任公司设立时的股东可以签订设立协议，明确各自在公司设立过程中的权利和义务。</p><h3 id="第四十四条" tabindex="-1">第四十四条 <a class="header-anchor" href="#第四十四条" aria-label="Permalink to &quot;第四十四条&quot;">​</a></h3><p>四条有限责任公司设立时的股东为设立公司从事的民事活动，其法律后果由公司承受。 公司未成立的，其法律后果由公司设立时的股东承受；设立时的股东为二人以上的，享有连带债权，承担连带债务。 设立时的股东为设立公司以自己的名义从事民事活动产生的民事责任，第三人有权选择请求公司或者公司设立时的股东承担。 设立时的股东因履行公司设立职责造成他人损害的，公司或者无过错的股东承担赔偿责任后，可以向有过错的股东追偿。</p><h3 id="第四十五条" tabindex="-1">第四十五条 <a class="header-anchor" href="#第四十五条" aria-label="Permalink to &quot;第四十五条&quot;">​</a></h3><p>五条设立有限责任公司，应当由股东共同制定公司章程。</p><h3 id="第四十六条" tabindex="-1">第四十六条 <a class="header-anchor" href="#第四十六条" aria-label="Permalink to &quot;第四十六条&quot;">​</a></h3><p>六条有限责任公司章程应当载明下列事项： （一）公司名称和住所； （二）公司经营范围； （三）公司注册资本； （四）股东的姓名或者名称； （五）股东的出资额、出资方式和出资日期； （六）公司的机构及其产生办法、职权、议事规则； （七）公司法定代表人的产生、变更办法； （八）股东会认为需要规定的其他事项。 股东应当在公司章程上签名或者盖章。</p><h3 id="第四十七条" tabindex="-1">第四十七条 <a class="header-anchor" href="#第四十七条" aria-label="Permalink to &quot;第四十七条&quot;">​</a></h3><p>七条有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额。全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。 法律、行政法规以及国务院决定对有限责任公司注册资本实缴、注册资本最低限额、股东出资期限另有规定的，从其规定。</p><h3 id="第四十八条" tabindex="-1">第四十八条 <a class="header-anchor" href="#第四十八条" aria-label="Permalink to &quot;第四十八条&quot;">​</a></h3><p>八条股东可以用货币出资，也可以用实物、知识产权、土地使用权、股权、债权等可以用货币估价并可以依法转让的非货币财产作价出资；但是，法律、行政法规规定不得作为出资的财产除外。 对作为出资的非货币财产应当评估作价，核实财产，不得高估或者低估作价。法律、行政法规对评估作价有规定的，从其规定。</p><h3 id="第四十九条" tabindex="-1">第四十九条 <a class="header-anchor" href="#第四十九条" aria-label="Permalink to &quot;第四十九条&quot;">​</a></h3><p>九条股东应当按期足额缴纳公司章程规定的各自所认缴的出资额。 股东以货币出资的，应当将货币出资足额存入有限责任公司在银行开设的账户；以非货币财产出资的，应当依法办理其财产权的转移手续。 股东未按期足额缴纳出资的，除应当向公司足额缴纳外，还应当对给公司造成的损失承担赔偿责任。</p><h3 id="第五十条" tabindex="-1">第五十条 <a class="header-anchor" href="#第五十条" aria-label="Permalink to &quot;第五十条&quot;">​</a></h3><p>十条有限责任公司设立时，股东未按照公司章程规定实际缴纳出资，或者实际出资的非货币财产的实际价额显著低于所认缴的出资额的，设立时的其他股东与该股东在出资不足的范围内承担连带责任。</p><h3 id="第五十一条" tabindex="-1">第五十一条 <a class="header-anchor" href="#第五十一条" aria-label="Permalink to &quot;第五十一条&quot;">​</a></h3><p>一条有限责任公司成立后，董事会应当对股东的出资情况进行核查，发现股东未按期足额缴纳公司章程规定的出资的，应当由公司向该股东发出书面催缴书，催缴出资。 未及时履行前款规定的义务，给公司造成损失的，负有责任的董事应当承担赔偿责任。</p><h3 id="第五十二条" tabindex="-1">第五十二条 <a class="header-anchor" href="#第五十二条" aria-label="Permalink to &quot;第五十二条&quot;">​</a></h3><p>二条股东未按照公司章程规定的出资日期缴纳出资，公司依照前条第一款规定发出书面催缴书催缴出资的，可以载明缴纳出资的宽限期；宽限期自公司发出催缴书之日起，不得少于六十日。宽限期届满，股东仍未履行出资义务的，公司经董事会决议可以向该股东发出失权通知，通知应当以书面形式发出。自通知发出之日起，该股东丧失其未缴纳出资的股权。 依照前款规定丧失的股权应当依法转让，或者相应减少注册资本并注销该股权；六个月内未转让或者注销的，由公司其他股东按照其出资比例足额缴纳相应出资。 股东对失权有异议的，应当自接到失权通知之日起三十日内，向人民法院提起诉讼。</p><h3 id="第五十三条" tabindex="-1">第五十三条 <a class="header-anchor" href="#第五十三条" aria-label="Permalink to &quot;第五十三条&quot;">​</a></h3><p>三条公司成立后，股东不得抽逃出资。 违反前款规定的，股东应当返还抽逃的出资；给公司造成损失的，负有责任的董事、监事、高级管理人员应当与该股东承担连带赔偿责任。</p><h3 id="第五十四条" tabindex="-1">第五十四条 <a class="header-anchor" href="#第五十四条" aria-label="Permalink to &quot;第五十四条&quot;">​</a></h3><p>四条公司不能清偿到期债务的，公司或者已到期债权的债权人有权要求已认缴出资但未届出资期限的股东提前缴纳出资。</p><h3 id="第五十五条" tabindex="-1">第五十五条 <a class="header-anchor" href="#第五十五条" aria-label="Permalink to &quot;第五十五条&quot;">​</a></h3><p>五条有限责任公司成立后，应当向股东签发出资证明书，记载下列事项： （一）公司名称； （二）公司成立日期； （三）公司注册资本； （四）股东的姓名或者名称、认缴和实缴的出资额、出资方式和出资日期； （五）出资证明书的编号和核发日期。 出资证明书由法定代表人签名，并由公司盖章。</p><h3 id="第五十六条" tabindex="-1">第五十六条 <a class="header-anchor" href="#第五十六条" aria-label="Permalink to &quot;第五十六条&quot;">​</a></h3><p>六条有限责任公司应当置备股东名册，记载下列事项： （一）股东的姓名或者名称及住所； （二）股东认缴和实缴的出资额、出资方式和出资日期； （三）出资证明书编号； （四）取得和丧失股东资格的日期。 记载于股东名册的股东，可以依股东名册主张行使股东权利。</p><h3 id="第五十七条" tabindex="-1">第五十七条 <a class="header-anchor" href="#第五十七条" aria-label="Permalink to &quot;第五十七条&quot;">​</a></h3><p>七条股东有权查阅、复制公司章程、股东名册、股东会会议记录、董事会会议决议、监事会会议决议和财务会计报告。 股东可以要求查阅公司会计账簿、会计凭证。股东要求查阅公司会计账簿、会计凭证的，应当向公司提出书面请求，说明目的。公司有合理根据认为股东查阅会计账簿、会计凭证有不正当目的，可能损害公司合法利益的，可以拒绝提供查阅，并应当自股东提出书面请求之日起十五日内书面答复股东并说明理由。公司拒绝提供查阅的，股东可以向人民法院提起诉讼。 股东查阅前款规定的材料，可以委托会计师事务所、律师事务所等中介机构进行。 股东及其委托的会计师事务所、律师事务所等中介机构查阅、复制有关材料，应当遵守有关保护国家秘密、商业秘密、个人隐私、个人信息等法律、行政法规的规定。 股东要求查阅、复制公司全资子公司相关材料的，适用前四款的规定。 第二节组织机构</p><h3 id="第五十八条" tabindex="-1">第五十八条 <a class="header-anchor" href="#第五十八条" aria-label="Permalink to &quot;第五十八条&quot;">​</a></h3><p>八条有限责任公司股东会由全体股东组成。股东会是公司的权力机构，依照本法行使职权。</p><h3 id="第五十九条" tabindex="-1">第五十九条 <a class="header-anchor" href="#第五十九条" aria-label="Permalink to &quot;第五十九条&quot;">​</a></h3><p>九条股东会行使下列职权： （一）选举和更换董事、监事，决定有关董事、监事的报酬事项； （二）审议批准董事会的报告； （三）审议批准监事会的报告； （四）审议批准公司的利润分配方案和弥补亏损方案； （五）对公司增加或者减少注册资本作出决议； （六）对发行公司债券作出决议； （七）对公司合并、分立、解散、清算或者变更公司形式作出决议； （八）修改公司章程； （九）公司章程规定的其他职权。 股东会可以授权董事会对发行公司债券作出决议。 对本条第一款所列事项股东以书面形式一致表示同意的，可以不召开股东会会议，直接作出决定，并由全体股东在决定文件上签名或者盖章。</p><h3 id="第六十条" tabindex="-1">第六十条 <a class="header-anchor" href="#第六十条" aria-label="Permalink to &quot;第六十条&quot;">​</a></h3><p>十条只有一个股东的有限责任公司不设股东会。股东作出前条第一款所列事项的决定时，应当采用书面形式，并由股东签名或者盖章后置备于公司。</p><h3 id="第六十一条" tabindex="-1">第六十一条 <a class="header-anchor" href="#第六十一条" aria-label="Permalink to &quot;第六十一条&quot;">​</a></h3><p>一条首次股东会会议由出资最多的股东召集和主持，依照本法规定行使职权。</p><h3 id="第六十二条" tabindex="-1">第六十二条 <a class="header-anchor" href="#第六十二条" aria-label="Permalink to &quot;第六十二条&quot;">​</a></h3><p>二条股东会会议分为定期会议和临时会议。 定期会议应当按照公司章程的规定按时召开。代表十分之一以上表决权的股东、三分之一以上的董事或者监事会提议召开临时会议的，应当召开临时会议。</p><h3 id="第六十三条" tabindex="-1">第六十三条 <a class="header-anchor" href="#第六十三条" aria-label="Permalink to &quot;第六十三条&quot;">​</a></h3><p>三条股东会会议由董事会召集，董事长主持；董事长不能履行职务或者不履行职务的，由副董事长主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事主持。 董事会不能履行或者不履行召集股东会会议职责的，由监事会召集和主持；监事会不召集和主持的，代表十分之一以上表决权的股东可以自行召集和主持。</p><h3 id="第六十四条" tabindex="-1">第六十四条 <a class="header-anchor" href="#第六十四条" aria-label="Permalink to &quot;第六十四条&quot;">​</a></h3><p>四条召开股东会会议，应当于会议召开十五日前通知全体股东；但是，公司章程另有规定或者全体股东另有约定的除外。 股东会应当对所议事项的决定作成会议记录，出席会议的股东应当在会议记录上签名或者盖章。</p><h3 id="第六十五条" tabindex="-1">第六十五条 <a class="header-anchor" href="#第六十五条" aria-label="Permalink to &quot;第六十五条&quot;">​</a></h3><p>五条股东会会议由股东按照出资比例行使表决权；但是，公司章程另有规定的除外。</p><h3 id="第六十六条" tabindex="-1">第六十六条 <a class="header-anchor" href="#第六十六条" aria-label="Permalink to &quot;第六十六条&quot;">​</a></h3><p>六条股东会的议事方式和表决程序，除本法有规定的外，由公司章程规定。 股东会作出决议，应当经代表过半数表决权的股东通过。 股东会作出修改公司章程、增加或者减少注册资本的决议，以及公司合并、分立、解散或者变更公司形式的决议，应当经代表三分之二以上表决权的股东通过。</p><h3 id="第六十七条" tabindex="-1">第六十七条 <a class="header-anchor" href="#第六十七条" aria-label="Permalink to &quot;第六十七条&quot;">​</a></h3><p>七条有限责任公司设董事会，本法第七十五条另有规定的除外。 董事会行使下列职权： （一）召集股东会会议，并向股东会报告工作； （二）执行股东会的决议； （三）决定公司的经营计划和投资方案； （四）制订公司的利润分配方案和弥补亏损方案； （五）制订公司增加或者减少注册资本以及发行公司债券的方案； （六）制订公司合并、分立、解散或者变更公司形式的方案； （七）决定公司内部管理机构的设置； （八）决定聘任或者解聘公司经理及其报酬事项，并根据经理的提名决定聘任或者解聘公司副经理、财务负责人及其报酬事项； （九）制定公司的基本管理制度； （十）公司章程规定或者股东会授予的其他职权。 公司章程对董事会职权的限制不得对抗善意相对人。</p><h3 id="第六十八条" tabindex="-1">第六十八条 <a class="header-anchor" href="#第六十八条" aria-label="Permalink to &quot;第六十八条&quot;">​</a></h3><p>八条有限责任公司董事会成员为三人以上，其成员中可以有公司职工代表。职工人数三百人以上的有限责任公司，除依法设监事会并有公司职工代表的外，其董事会成员中应当有公司职工代表。董事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生。 董事会设董事长一人，可以设副董事长。董事长、副董事长的产生办法由公司章程规定。</p><h3 id="第六十九条" tabindex="-1">第六十九条 <a class="header-anchor" href="#第六十九条" aria-label="Permalink to &quot;第六十九条&quot;">​</a></h3><p>九条有限责任公司可以按照公司章程的规定在董事会中设置由董事组成的审计委员会，行使本法规定的监事会的职权，不设监事会或者监事。公司董事会成员中的职工代表可以成为审计委员会成员。</p><h3 id="第七十条" tabindex="-1">第七十条 <a class="header-anchor" href="#第七十条" aria-label="Permalink to &quot;第七十条&quot;">​</a></h3><p>十条董事任期由公司章程规定，但每届任期不得超过三年。董事任期届满，连选可以连任。 董事任期届满未及时改选，或者董事在任期内辞任导致董事会成员低于法定人数的，在改选出的董事就任前，原董事仍应当依照法律、行政法规和公司章程的规定，履行董事职务。 董事辞任的，应当以书面形式通知公司，公司收到通知之日辞任生效，但存在前款规定情形的，董事应当继续履行职务。</p><h3 id="第七十一条" tabindex="-1">第七十一条 <a class="header-anchor" href="#第七十一条" aria-label="Permalink to &quot;第七十一条&quot;">​</a></h3><p>一条股东会可以决议解任董事，决议作出之日解任生效。 无正当理由，在任期届满前解任董事的，该董事可以要求公司予以赔偿。</p><h3 id="第七十二条" tabindex="-1">第七十二条 <a class="header-anchor" href="#第七十二条" aria-label="Permalink to &quot;第七十二条&quot;">​</a></h3><p>二条董事会会议由董事长召集和主持；董事长不能履行职务或者不履行职务的，由副董事长召集和主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事召集和主持。</p><h3 id="第七十三条" tabindex="-1">第七十三条 <a class="header-anchor" href="#第七十三条" aria-label="Permalink to &quot;第七十三条&quot;">​</a></h3><p>三条董事会的议事方式和表决程序，除本法有规定的外，由公司章程规定。 董事会会议应当有过半数的董事出席方可举行。董事会作出决议，应当经全体董事的过半数通过。 董事会决议的表决，应当一人一票。 董事会应当对所议事项的决定作成会议记录，出席会议的董事应当在会议记录上签名。</p><h3 id="第七十四条" tabindex="-1">第七十四条 <a class="header-anchor" href="#第七十四条" aria-label="Permalink to &quot;第七十四条&quot;">​</a></h3><p>四条有限责任公司可以设经理，由董事会决定聘任或者解聘。 经理对董事会负责，根据公司章程的规定或者董事会的授权行使职权。经理列席董事会会议。</p><h3 id="第七十五条" tabindex="-1">第七十五条 <a class="header-anchor" href="#第七十五条" aria-label="Permalink to &quot;第七十五条&quot;">​</a></h3><p>五条规模较小或者股东人数较少的有限责任公司，可以不设董事会，设一名董事，行使本法规定的董事会的职权。该董事可以兼任公司经理。</p><h3 id="第七十六条" tabindex="-1">第七十六条 <a class="header-anchor" href="#第七十六条" aria-label="Permalink to &quot;第七十六条&quot;">​</a></h3><p>六条有限责任公司设监事会，本法第六十九条、第八十三条另有规定的除外。 监事会成员为三人以上。监事会成员应当包括股东代表和适当比例的公司职工代表，其中职工代表的比例不得低于三分之一，具体比例由公司章程规定。监事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生。 监事会设主席一人，由全体监事过半数选举产生。监事会主席召集和主持监事会会议；监事会主席不能履行职务或者不履行职务的，由过半数的监事共同推举一名监事召集和主持监事会会议。 董事、高级管理人员不得兼任监事。</p><h3 id="第七十七条" tabindex="-1">第七十七条 <a class="header-anchor" href="#第七十七条" aria-label="Permalink to &quot;第七十七条&quot;">​</a></h3><p>七条监事的任期每届为三年。监事任期届满，连选可以连任。 监事任期届满未及时改选，或者监事在任期内辞任导致监事会成员低于法定人数的，在改选出的监事就任前，原监事仍应当依照法律、行政法规和公司章程的规定，履行监事职务。</p><h3 id="第七十八条" tabindex="-1">第七十八条 <a class="header-anchor" href="#第七十八条" aria-label="Permalink to &quot;第七十八条&quot;">​</a></h3><p>八条监事会行使下列职权： （一）检查公司财务； （二）对董事、高级管理人员执行职务的行为进行监督，对违反法律、行政法规、公司章程或者股东会决议的董事、高级管理人员提出解任的建议； （三）当董事、高级管理人员的行为损害公司的利益时，要求董事、高级管理人员予以纠正； （四）提议召开临时股东会会议，在董事会不履行本法规定的召集和主持股东会会议职责时召集和主持股东会会议； （五）向股东会会议提出提案； （六）依照本法第一百八十九条的规定，对董事、高级管理人员提起诉讼； （七）公司章程规定的其他职权。</p><h3 id="第七十九条" tabindex="-1">第七十九条 <a class="header-anchor" href="#第七十九条" aria-label="Permalink to &quot;第七十九条&quot;">​</a></h3><p>九条监事可以列席董事会会议，并对董事会决议事项提出质询或者建议。 监事会发现公司经营情况异常，可以进行调查；必要时，可以聘请会计师事务所等协助其工作，费用由公司承担。</p><h3 id="第八十条" tabindex="-1">第八十条 <a class="header-anchor" href="#第八十条" aria-label="Permalink to &quot;第八十条&quot;">​</a></h3><p>十条监事会可以要求董事、高级管理人员提交执行职务的报告。 董事、高级管理人员应当如实向监事会提供有关情况和资料，不得妨碍监事会或者监事行使职权。</p><h3 id="第八十一条" tabindex="-1">第八十一条 <a class="header-anchor" href="#第八十一条" aria-label="Permalink to &quot;第八十一条&quot;">​</a></h3><p>一条监事会每年度至少召开一次会议，监事可以提议召开临时监事会会议。 监事会的议事方式和表决程序，除本法有规定的外，由公司章程规定。 监事会决议应当经全体监事的过半数通过。 监事会决议的表决，应当一人一票。 监事会应当对所议事项的决定作成会议记录，出席会议的监事应当在会议记录上签名。</p><h3 id="第八十二条" tabindex="-1">第八十二条 <a class="header-anchor" href="#第八十二条" aria-label="Permalink to &quot;第八十二条&quot;">​</a></h3><p>二条监事会行使职权所必需的费用，由公司承担。</p><h3 id="第八十三条" tabindex="-1">第八十三条 <a class="header-anchor" href="#第八十三条" aria-label="Permalink to &quot;第八十三条&quot;">​</a></h3><p>三条规模较小或者股东人数较少的有限责任公司，可以不设监事会，设一名监事，行使本法规定的监事会的职权；经全体股东一致同意，也可以不设监事。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',87)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
